def split_feed(records):
    clean, rejected, seen = [], [], set()
    for r in records:
        parts = r["email"].split("@")
        reason = "invalid email" if len(parts) != 2 or not all(parts) else "duplicate email" if r["email"] in seen else None
        if reason:
            rejected.append({**r, "reason": reason})
        else:
            clean.append(dict(r))
            seen.add(r["email"])
    return clean, rejected
