def price_cart(cart, rules):
    base = subtotal(cart)
    discount = (base * rules["discount_percent"] + 50) // 100 if base >= rules["threshold"] else 0
    tax = ((base - discount) * rules["tax_percent"] + 50) // 100
    return {"subtotal": base, "discount": discount, "tax": tax, "total": base - discount + tax}
totals = price_cart(cart, rules)

