def upsert(base, incoming):
    state = {r["id"]: dict(r) for r in base}
    for r in incoming:
        old = state.get(r["id"])
        if old is None or r["version"] > old["version"]:
            state[r["id"]] = dict(r)
    return [state[key] for key in sorted(state)]
